let toastTimer,previousFocus;
function toast(message){const el=document.getElementById('toast');el.textContent=tr(message);el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000)}
function heading(title,subtitle='',extra=''){return `<div class="page-heading between"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra}</div>`;}
function cardHeading(title,link='',target=''){return `<div class="card-heading"><h2>${title}</h2>${link?`<button class="text-link" data-page="${target}">${link} ${icon('right','sm')}</button>`:''}</div>`;}
function btn(label,action,cls='primary',data=''){return `<button class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function tag(status){const c=({Présent:'mint','En retard':'orange',Absent:'red','En attente':'orange',Validé:'mint',Refusé:'red'})[status]||'blue';return `<span class="tag ${c}">${icon(c==='mint'?'check':c==='red'?'close':'clock','sm')}${esc(status)}</span>`;}
function roleOptions(value){return Object.entries(roles).map(([k,r])=>`<option value="${k}" ${value===k?'selected':''}>${r.space}</option>`).join('')}
function sidebar(){return renderRoleSidebar()}
function topbar(){return renderRoleTopbar()}
function footer(){return `<footer class="footer"><span class="flex gap">${icon('shield')}Une école accessible, où que l’on soit.</span><span>Fait pour apprendre à son rythme. ${icon('heart')}</span></footer>`;}
function routes(){return resolveRoleRoute()}
function go(page,role=state.role){return goToOwnPage(page,role)}
function changeRole(role,teacherId){if(!roles[role])return;closeLibraryReader();checkpointGame();clearTimeout(state.memoryTimer);state.activeGame=null;state.courseClass='all';state.libraryClass='all';state.librarySubject='all';state.libraryLanguage='all';state.resourceType='all';state.resourceSearch='';state.resourceSavedOnly=false;state.coachOpen=false;resetAICoach();resetTeacherCoach();state.planningClass='all';state.planningTeacher='all';state.planningScope='class';state.planningQueue=false;state.calendarDate=dayKey();if(role==='professeur')state.teacherId=teacherId||activeTeacher()?.id||'';state.role=role;state.messageDrafts={};state.attachment=null;state.contactFilter='toutes';state.contactSearch='';state.assignmentFilter='all';state.attendance.class='all';state.rosterClass='all';state.rosterSearch='';persist();go('dashboard',role)}
function render(){
  const scroll=schoolScrollSnapshot();
  routes();
  applyLanguage();
  document.body.dataset.space=state.role;
  document.body.dataset.view=state.page;
  document.documentElement.style.setProperty('--scale',state.fontScale);
  document.body.classList.toggle('fatigue-mode',state.fatigue);
  const views={jeux:gamesPage,dashboard:dashboard,accueil:welcome,courses:coursesPage,coach:teacherCoachPage,calendrier:calendarPage,rattrapage:catchupPage,devoirs:renderHomeworkPage,notes:gradesPage,resources:resourcesPage,messagerie:messagesPage,presences:attendancePage,classes:classesPage,eleves:studentsPage,comptes:accountsPage,statistiques:statisticsPage,parametres:settingsPage,assistance:helpPage,'bien-etre':wellbeingPage};
  const view=state.page==='connexion' ? profileScreen() : sidebar()+`<div class="workspace">${topbar()}<main id="main" class="content" tabindex="-1">${views[state.page]()}${footer()}</main>${mobileNavigation()}</div>`;
  document.getElementById('app').innerHTML=localizeHTML(view);
  restoreSchoolScroll(scroll);
  document.title=`${tr(rolePageTitle())} — ${tr('Madrassati Maâk')}`;
  persist();
  refreshGradePeriod();
  scrollChats();
  if(state.page==='coach'&&!teacherCoach.access)checkTeacherCoachAccess();
}
function scrollChats(){for(const id of ['chatMessages','coachChat','aiCoachChat']){const el=document.getElementById(id);if(el)el.scrollTop=el.scrollHeight}}
function fatigueToggle(){return `<button class="fatigue-pill ${state.fatigue?'active':''}" data-action="fatigue" aria-pressed="${state.fatigue}">${icon('moon')}Mode fatigue ${state.fatigue?'activé':''}</button>`;}
function dashboard(){if(state.role==='parent')return parentDashboard();if(state.role==='professeur')return teacherDashboard();if(state.role==='administration')return adminDashboard();return studentDashboard()}
function homeworkRows(){return homeworkList().filter(a=>homeworkCanEdit(a.id)).slice(0,3).map(homeworkRow).join('')}
function subjectsGrid(){return `<div class="subject-grid">${subjects.map(s=>`<button class="subject-card" data-action="subject" data-id="${s.id}">${tile(s.icon,s.color)}<strong>${s.name}</strong>${progress(s.progress,s.color==='mint'?'var(--mint)':s.color==='orange'?'var(--orange)':s.color==='purple'?'var(--purple)':s.color==='red'?'var(--red)':'var(--blue)')}<small>${s.progress}%</small></button>`).join('')}</div>`;}
function studentDashboard(){return renderStudentExperience()}
function statCard(i,c,label,value,caption){return `<div class="stat-card">${tile(i,c)}<div><p class="stat-label">${label}</p><div class="stat-number">${value}</div>${caption?`<p class="stat-caption">${caption}</p>`:''}</div></div>`;}
function generatorCard(){return `<section class="card generator">${cardHeading(`${icon('clipboard')} Exercices d’exemple`)}<div class="form-field"><label for="genLevel">Niveau</label><select id="genLevel">${['6ᵉ','5ᵉ','4ᵉ','3ᵉ','CM2','2ᵉ BAC'].map(l=>`<option ${state.generator.level===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label for="genSubject">Matière</label><select id="genSubject">${['SVT','Mathématiques','Français'].map(l=>`<option ${state.generator.subject===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label for="genLesson">Leçon</label><select id="genLesson">${generatorLessons().map(l=>`<option ${state.generator.lesson===l?'selected':''}>${l}</option>`).join('')}</select></div>${btn(`${icon('spark','sm')} Générer des exercices`,'generate','primary full')}<div class="question-preview"><h3>Aperçu des questions</h3>${state.editingQuestions?`<label class="sr-only" for="editedQuestions">Questions, une par ligne</label><textarea id="editedQuestions">${esc((state.lang==='ar'?state.generated.map(q=>tr(q)):state.generated).join('\n'))}</textarea>`:`<ol>${state.generated.map(q=>`<li>${esc(q)}</li>`).join('')}</ol>`}</div><div class="generator-actions">${btn(`${icon('edit','sm')} ${state.editingQuestions?'Appliquer':'Modifier'}`,'edit-questions','secondary')}${btn(`${icon('file','sm')} Exporter PDF`,'export-questions','mint')}${btn(`${icon('save','sm')} Enregistrer`,'save-questions','secondary')}</div><p class="tiny muted mt">Une base d’exercices à adapter au rythme de votre classe.</p></section>`;}
function generatorLessons(){return state.generator.subject==='SVT'?['La cellule : unité et diversité du vivant','Le corps humain']:state.generator.subject==='Mathématiques'?['Les équations de premier degré','Fractions et opérations']:['Le texte descriptif','Le groupe nominal']}
