function exampleGrades(){return `<div class="grades-summary"><div class="metric"><span>MOYENNE GÉNÉRALE</span><strong>14,2<small>/20</small></strong><p>↗ +1,4 point ce trimestre</p></div><div class="metric"><span>PROGRESSION</span><strong>78%</strong><p>Objectif du mois : 80%</p></div><div class="metric"><span>ASSIDUITÉ</span><strong>92%</strong><p>Chaque présence compte</p></div></div><div class="grades-layout"><section class="card">${cardHeading('Notes d’exemple')}<div class="table-scroll"><table class="data-table"><thead><tr><th>Matière</th><th>Évaluation</th><th>Date</th><th>Note / 20</th></tr></thead><tbody>${[['Mathématiques','Équations','16/05/2025','15,5'],['Français','Expression écrite','14/05/2025','14'],['SVT','La cellule','12/05/2025','16'],['Histoire-Géographie','Repères géographiques','09/05/2025','13'],['Anglais','Daily routine','07/05/2025','12,5']].map(([s,e,d,n])=>`<tr><td>${s}</td><td>${e}</td><td>${d}</td><td><span class="tag mint">${n}</span></td></tr>`).join('')}</tbody></table></div></section><section class="card">${cardHeading('Mes progrès par matière')}${subjects.map(s=>`<div class="subject-progress-row">${tile(s.icon,s.color)}<div><h4>${s.name}</h4>${progress(s.progress)}</div><strong>${s.progress}%</strong></div>`).join('')}</section></div><section class="wellbeing-strip mt">${icon('award')}<div><h3>Des progrès qui méritent d’être célébrés.</h3><p>Ta régularité et ta curiosité font la différence. Continue ainsi !</p></div></section>`;}
