function messagesPage(){const c=roleContacts().find(x=>x.id===state.contact)||roleContacts()[0];state.contact=c.id;const messages=state.messages[messageThreadKey()]||defaultThreadMessages(c);return `${heading('Messagerie',state.role==='professeur'?'Parents et équipe pédagogique':'')}<div class="message-layout"><aside class="conversation-list"><div class="search-box">${icon('search')}<label class="sr-only" for="contactSearch">Rechercher une conversation</label><input id="contactSearch" placeholder="Rechercher une conversation…" value="${esc(state.contactSearch)}"></div><div class="tabs">${[['toutes','Toutes'],['nonlues','Non lues'],[state.role==='professeur'?'parents':'enseignants',state.role==='professeur'?'Parents':'Enseignants'],['administration',state.role==='professeur'?'Équipe':'Admin.']].map(([v,l])=>`<button class="tab ${state.contactFilter===v?'active':''}" data-action="contact-filter" data-value="${v}" aria-pressed="${state.contactFilter===v}">${l}</button>`).join('')}</div><div class="contacts" id="contactsList">${contactsList()}</div></aside><section class="conversation-center" aria-label="Conversation avec ${c.name}"><div class="conversation-header">${avatar(c.initial,c.color)}<div><h2>${c.name}</h2><p>${c.sub}</p></div><div class="tools"><button class="icon-button" data-action="join" aria-label="Ouvrir l’aperçu d’une séance">${icon('video')}</button><button class="icon-button" data-action="contact-details" aria-label="Voir les détails de la conversation">${icon('info')}</button></div></div><div class="chat-class">${icon('cap')}Classe concernée : ${esc(childClassName())}</div><div class="conversation-messages" id="chatMessages">${messages.length?'<div class="chat-day">Aujourd’hui</div>':'<p class="message-empty">Aucun message dans cette conversation.</p>'}${messages.map(m=>`<div class="message ${m.own?'own':''}">${m.own?'':avatar(c.initial,c.color)}<div class="bubble"><span class="message-text" dir="auto" data-no-i18n="${m.own?'true':'false'}">${esc(m.text)}</span><span class="time">${esc(m.time)}${m.own?' · Envoyé ✓':''}</span></div></div>`).join('')}</div><div class="conversation-compose"><form id="messageForm" class="message-form"><button type="button" class="icon-button" data-action="attach" aria-label="Joindre un fichier">${icon('paperclip')}</button><input type="file" id="messageAttachment" class="hidden"><label class="sr-only" for="messageInput">Votre message</label><input id="messageInput" name="message" value="${esc(state.messageDrafts[messageThreadKey()]||'')}" placeholder="Écrivez votre message…" autocomplete="off" maxlength="2000"><button class="btn primary" type="submit">${icon('send','sm')}<span>Envoyer</span></button></form>${state.attachment?`<div class="attachment-chip">${icon('file')}${esc(state.attachment)}<button data-action="remove-attachment" aria-label="Retirer la pièce jointe">${icon('close')}</button></div>`:state.examples&&c.id==='amal'&&state.role!=='professeur'?`<div class="attachment-chip">${icon('file')}ExerciceSupplementaire_6A.pdf · 2 pages<button class="text-link" data-action="chat-file">Télécharger</button></div>`:''}<p class="message-local-note">Les messages de cette maquette sont enregistrés uniquement dans votre navigateur.</p></div></section><aside class="conversation-details"><div class="card-heading"><h2>Détails de la conversation</h2>${icon('info')}</div><div class="contact-details">${avatar(c.initial,c.color,'large online')}<h3>${c.name}</h3><p>${c.sub}</p></div><div class="detail-line">${icon('cap')}Classe : ${esc(childClassName())}</div><div class="detail-line">${icon('book')}Matière : ${c.subject}</div><div class="mt session-list">${cardHeading('Prochaines séances')}${sessionRows()}</div><button class="text-link mt" data-page="assistance">Besoin d’aide ? ${icon('arrow','sm')}</button></aside></div>`;}
function contactsList(){
  const query=searchKey(state.contactSearch);
  const contacts=roleContacts().filter(c=>{
    const matchesFilter=state.contactFilter==='toutes'||state.contactFilter===c.type||(state.contactFilter==='nonlues'&&state.examples&&c.unread);
    return matchesFilter&&searchKey(`${c.name} ${tr(c.name)}`).includes(query);
  });
  return contacts.map(c=>{
    const unread=state.examples?c.unread:0;
    return `<button class="contact-row ${state.contact===c.id?'active':''}" data-action="contact" data-id="${c.id}" aria-pressed="${state.contact===c.id}">${avatar(c.initial,c.color)}<div><strong>${c.name}</strong><small>${c.sub}</small>${unread?`<small class="green">${unread} message${unread>1?'s':''} non lu${unread>1?'s':''}</small>`:''}</div>${state.examples?`<div class="contact-meta">${c.time}${unread?'<span class="unread-dot"></span>':''}</div>`:''}</button>`;
  }).join('')||empty('Aucun résultat','Ajustez votre recherche.');
}
function formatDate(d,opts={day:'numeric',month:'long'}){return d.toLocaleDateString(state.lang==='ar'?'ar-MA-u-ca-gregory-nu-latn':'fr-FR',opts)}
function attendancePage(){if(state.role==='parent')return parentAttendancePage();const f=state.attendance,list=filteredAttendance();return `${heading('Suivi des présences','Un suivi attentif pour mieux accompagner chaque élève.',`<button class="text-link" data-page="calendrier">Voir le calendrier ${icon('arrow','sm')}</button>`)}<div class="filters"><div class="filter-field"><label for="attendanceClass">Classe</label><select id="attendanceClass">${libraryOptions([['all','Toutes les classes'],...publicationClasses().map(c=>[c.id,c.name])],f.class)}</select></div><div class="filter-field"><label for="attendanceLevel">Niveau</label><select id="attendanceLevel">${[['all','Tous les niveaux'],['Primaire','Primaire'],['Collège','Collège'],['Lycée','Lycée']].map(([v,l])=>`<option value="${v}" ${f.level===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="filter-field"><label for="attendanceSubject">Matière</label><select id="attendanceSubject">${libraryOptions(subjects.map(s=>[s.name,s.name]),f.subject)}</select></div><div class="filter-field"><label for="attendancePeriod">Période</label><select id="attendancePeriod"><option value="week" ${f.period==='week'?'selected':''}>Semaine en cours</option><option value="month" ${f.period==='month'?'selected':''}>Mois en cours</option>${state.examples?`<option value="example" ${f.period==='example'?'selected':''}>Période d’exemple</option>`:''}</select></div><div class="filter-field"><label for="attendanceSearch">Recherche</label><div class="search-box">${icon('search')}<input id="attendanceSearch" placeholder="Rechercher un élève…" value="${esc(f.search)}"></div></div></div><div class="stats-grid" id="attendanceStats">${attendanceStats(list)}</div><div class="attendance-layout"><section class="card" id="attendanceResults">${attendanceTable(list)}</section><aside class="stack">${btn(`${icon('download','sm')} Exporter le rapport`,'export-attendance','primary full')}<section class="security-card">${icon('shield')}<h3>Données de démonstration</h3><p>Cette maquette utilise des profils fictifs. Les essais sont conservés dans votre navigateur.</p>${icon('lock','lock')}</section></aside></div>`;}
function wellbeingPage(){if(state.role==='parent')return parentWellbeingPage();return `${heading('Mon espace bien-être','Ici, tu peux ralentir. Prendre soin de toi fait aussi partie du chemin.')}<div class="wellbeing-layout"><section class="wellbeing-hero">${tile('heart','mint')}<h2>Comment te sens-tu aujourd’hui ?</h2><p>Tu n’as pas besoin d’être en forme tous les jours. Écouter ce que tu ressens, c’est déjà prendre soin de toi.</p><div class="mood-picker">${[['great','😊','En forme'],['calm','🙂','Ça va'],['tired','😴','Fatigué'],['sad','😔','Pas très bien']].map(([v,e,l])=>`<button class="mood-button ${state.mood===v?'selected':''}" data-action="mood" data-value="${v}"><span>${e}</span>${l}</button>`).join('')}</div><p class="mt" id="moodFeedback">${moodText()}</p><div class="mt">${fatigueToggle()}</div></section><section class="card text-center">${cardHeading('Une minute pour respirer')}<p class="tiny muted">Suis le cercle : inspire quand il grandit, expire quand il rétrécit. Reprends ton rythme naturel quand tu le souhaites.</p><div class="breathing-circle ${state.breathing?'running':''}" id="breathingCircle"><span>${state.breathing?'Inspire… expire…':'À ton rythme'}</span></div>${btn(`${icon('heart','sm')} ${state.breathing?'Terminer la pause':'Commencer ma pause'}`,'breathe','mint')}<p class="tiny muted mt">Un moment de calme, sans objectif à atteindre.</p></section></div><section class="card mt">${cardHeading('Tu n’es pas seul')}<p class="tiny muted">Si tu en ressens le besoin, parle à un proche, à ton professeur ou à une personne de confiance. Tes émotions méritent d’être écoutées.</p><button class="text-link mt" data-page="messagerie">Écrire à un professeur ${icon('arrow','sm')}</button></section>`;}
function moodText(){return ({great:'Quelle belle énergie ! Garde aussi du temps pour te reposer.',calm:'Un moment tranquille, c’est bien aussi. Avance à ton rythme.',tired:'On peut faire plus court aujourd’hui. Le mode fatigue est là pour ça.',sad:'Merci d’avoir partagé ce que tu ressens. Une personne de confiance peut t’écouter.'})[state.mood]||'Choisis ce qui ressemble le plus à ton humeur. Tu peux changer à tout moment.'}
function settingsPage(){const admin=state.role==='administration';return `${admin ? heading('Paramètres') : heading('Mes préférences','Un espace plus confortable, à votre rythme.')}<section class="card settings-card">${languageSettings()}${exampleSettings()}<div class="setting-row"><div><h3>Taille du texte</h3><p>Pour lire plus confortablement.</p></div><label class="sr-only" for="fontScale">Taille du texte</label><select id="fontScale">${[[1,'Standard'],[1.1,'Grande'],[1.2,'Très grande']].map(([v,l])=>`<option value="${v}" ${state.fontScale===v?'selected':''}>${l}</option>`).join('')}</select></div>${admin ? '' : `<div class="setting-row"><div><h3>Mode fatigue</h3><p>Privilégier les séances courtes.</p></div><button class="switch ${state.fatigue?'on':''}" role="switch" aria-checked="${state.fatigue}" aria-label="Mode fatigue" data-action="fatigue"><span></span></button></div><div class="setting-row"><div><h3>Rappels de séance</h3><p>Afficher les rappels dans cette maquette.</p></div><button class="switch ${state.notify?'on':''}" role="switch" aria-checked="${state.notify}" aria-label="Rappels de séance" data-action="toggle-notify"><span></span></button></div>`}<div class="setting-row" style="border:0"><div><h3>Recommencer la démonstration</h3><p>Effacer les essais enregistrés dans ce navigateur.</p></div>${btn('Réinitialiser','reset-confirm','secondary small')}</div></section>`;}
function helpPage(){return `${heading('Un soutien à vos côtés','Une question, une difficulté ? Commençons par en parler.')}<div class="help-layout"><section class="card">${cardHeading('Questions fréquentes')}<div class="faq-list"><details open><summary>Comment rejoindre ma prochaine séance ?</summary><p>Depuis votre tableau de bord ou le calendrier, choisissez « Rejoindre la séance ». Cette maquette ouvre un aperçu de classe ; la visioconférence sera à connecter dans l’application finale.</p></details><details><summary>Comment déposer un devoir ?</summary><p>Ouvrez « Devoirs », puis sélectionnez votre activité. Le bouton « Joindre mon travail » permet de choisir un fichier sur votre appareil. Dans la maquette, seul son nom est enregistré.</p></details><details><summary>Je suis fatigué : puis-je suivre une séance plus courte ?</summary><p>Activez le mode fatigue depuis votre tableau de bord ou votre espace bien-être. La durée affichée s’adapte à une séance courte de 15 minutes.</p></details><details><summary>Comment sont créés les comptes ?</summary><p>L’administration crée les accès pour les élèves, leurs parents et les professeurs. Cette maquette permet de découvrir chaque espace depuis la page de connexion, en choisissant un profil.</p></details><details><summary>Mes essais sont-ils envoyés à quelqu’un ?</summary><p>Non. Les messages, fichiers sélectionnés et formulaires sont simulés dans votre navigateur. Aucun échange n’est transmis à un professeur ou à une administration.</p></details></div></section><section class="card help-card">${tile('headset','mint')}<h2 class="mt">Parlons de votre besoin</h2><p>Décrivez votre question. Vous pourrez conserver votre demande pour la transmettre à votre établissement.</p><form class="form" id="helpForm"><div><label for="helpSubject">Votre sujet</label><select id="helpSubject" name="subject"><option>Connexion à mon compte</option><option>Rejoindre une séance</option><option>Déposer un devoir</option><option>Autre question</option></select></div><div><label for="helpMessage">Votre question</label><textarea id="helpMessage" name="message" placeholder="Comment pouvons-nous vous aider ?" required></textarea></div><button class="btn mint" type="submit">${icon('download','sm')}Conserver ma demande</button></form></section></div>`;}

/* Modales accessibles, avec restauration du focus et fermeture par Échap. */
function openModal(title,body,wide=false,extraClass=''){clearSessionPreview();closeLibraryReader();previousFocus=document.activeElement;document.getElementById('modal-root').innerHTML=localizeHTML(`<div class="modal-backdrop"><section class="modal ${wide?'wide':''} ${extraClass}" role="dialog" aria-modal="true" aria-labelledby="modalTitle" tabindex="-1"><div class="modal-header"><h2 id="modalTitle">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div>${body}</section></div>`);document.body.style.overflow='hidden';document.querySelector('.modal').focus({preventScroll:true})}
function closeModal(){gradebookEditor=null;clearSessionPreview();const readerId=libraryReader?.id;closeLibraryReader();if('speechSynthesis' in window)speechSynthesis.cancel();document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';if(readerId&&state.page==='resources'){render();const opener=[...document.querySelectorAll('[data-action="resource-open"]')].find(button=>button.dataset.id===readerId);(opener||document.getElementById('main'))?.focus({preventScroll:true})}else if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true})}
