 'close-menu':()=>{document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-overlay').classList.remove('visible');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');document.body.style.overflow='';document.querySelector('.mobile-toggle')?.focus()},
