function togglePopover(id,trigger){const el=document.getElementById(id);const open=el.classList.contains('hidden');closePopovers();if(open){el.classList.remove('hidden');trigger?.setAttribute('aria-expanded','true')}}
function closePopovers(){document.querySelectorAll('.popover').forEach(el=>el.classList.add('hidden'));document.querySelectorAll('[aria-expanded]').forEach(el=>el.setAttribute('aria-expanded','false'))}
document.addEventListener('change',event=>{const el=event.target,id=el.id;if(rememberTeacherCoachInput(el)||updateLibraryFilter(el)||updateSessionForm(el)||updateGradebookClass(el))return;if(id==='demoTeacher'){loginTeacherId=el.value;return}if(id==='newAccountRole'){syncAccountFields(el);return}if(id==='coachExercise'){chooseCoachExercise(el.value);return}if(id==='courseClassFilter'&&state.role==='professeur'){state.courseClass=el.value;render();document.getElementById(id)?.focus();return}if(id==='calendarClass'||id==='calendarTeacher'){state[id==='calendarClass'?'planningClass':'planningTeacher']=el.value;render();document.getElementById(id)?.focus();return}if(id==='libraryPage'){moveLibraryPage(el.value);return}if(updateLibraryEditor(el))return;if(id==='homeworkKind'){document.getElementById('homeworkPublishLabel').textContent=tr(el.value==='exam'?'Publier l’examen':'Publier le devoir');return}if(id==='homeworkClass'){const select=document.getElementById('homeworkResource');select.innerHTML=localizeHTML(libraryHomeworkResourceOptions(el.value));return}if(id==='assignmentFile'){attachHomeworkFile(el);return}if(el.name==='homeworkVariant'&&el.form?.id==='homeworkResponseForm'){if(saveHomeworkDraft(el.form))refreshHomework(el.form.dataset.id);return}const handlers={languageSelect:()=>setLanguage(el.value),gameDifficulty:()=>{state.gameDifficulty=el.value==='explorateur'?'explorateur':'decouverte';persist();render()},fontScale:()=>{state.fontScale=Number(el.value);persist();render()},attendanceClass:()=>{state.attendance.class=el.value;render()},attendanceLevel:()=>{state.attendance.level=el.value;render()},attendanceSubject:()=>{state.attendance.subject=el.value;render()},attendancePeriod:()=>{state.attendance.period=el.value;render()},studentClass:()=>{state.rosterClass=el.value;render();document.getElementById(id)?.focus()},accountRole:()=>{state.accountRole=el.value;render();document.getElementById(id)?.focus()},accountStatus:()=>{state.accountStatus=el.value;render();document.getElementById(id)?.focus()},genLevel:()=>{state.generator.level=el.value},genSubject:()=>{state.generator.subject=el.value;state.generator.lesson=generatorLessons()[0];render()},genLesson:()=>{state.generator.lesson=el.value},messageAttachment:()=>{if(el.files[0]){state.attachment=el.files[0].name;render()}}};handlers[id]?.()});
document.addEventListener('input',event=>{const el=event.target;if(el.form?.id==='sessionForm')clearSessionPreview();if(rememberTeacherCoachInput(el))return;if(el.id==='coachAIInput'){aiCoach.draft=el.value;return}if(el.id==='homeworkResponse'){saveHomeworkDraft(el.form);return}const handlers={rosterSearch:()=>{state.rosterSearch=el.value;document.getElementById('rosterResults').innerHTML=localizeHTML(studentRosterResults())},messageInput:()=>{state.messageDrafts[messageThreadKey()]=el.value},quickSearchInput:()=>{quickSearchValue=el.value;document.getElementById('catalogResults').innerHTML=localizeHTML(quickSearchResults())},resourceSearch:()=>{state.resourceSearch=el.value;document.getElementById('resourceResults').innerHTML=localizeHTML(resourceLibraryResults());const count=document.getElementById('resourceCount');if(count)count.textContent=filteredResourceList().length},contactSearch:()=>{state.contactSearch=el.value;document.getElementById('contactsList').innerHTML=localizeHTML(contactsList())},accountSearch:()=>updateAdminAccountSearch(el),attendanceSearch:()=>{state.attendance.search=el.value;const list=filteredAttendance();document.getElementById('attendanceResults').innerHTML=localizeHTML(attendanceTable(list));document.getElementById('attendanceStats').innerHTML=localizeHTML(attendanceStats(list))}};handlers[el.id]?.()});
document.addEventListener('submit',event=>{const form=event.target;const values=Object.fromEntries(new FormData(form));if(handleLibraryForm(form,values)||handleHomeworkForm(form,values)){event.preventDefault();return}if(!['loginForm','messageForm','coachForm','coachAIForm','teacherCoachForm','gradebookForm','gradePeriodForm','accountForm','studentClassForm','sessionForm','helpForm'].includes(form.id))return;event.preventDefault();if(!isRoleFormAllowed(form.id)){toast('Ce formulaire n’est pas disponible dans votre espace.');return}
 if(form.id==='gradebookForm'){saveGradebookForm(form,values);return}
 if(form.id==='gradePeriodForm'){saveGradePeriod(form,values);return}
 if(form.id==='loginForm'){let valid=true;for(const field of ['identifier','password']){const input=document.getElementById(field),missing=!input.value.trim();input.classList.toggle('invalid',missing);document.getElementById(field+'Error').textContent=missing?tr(`Veuillez saisir ${field==='identifier'?'votre identifiant':'votre mot de passe'}.`):'';valid&&=!missing}if(valid){changeRole(loginRole,loginRole==='professeur'?teacherForIdentifier(values.identifier)?.id:undefined);toast('Bienvenue dans votre espace de démonstration.')}return}
 if(form.id==='messageForm'){const text=String(values.message||'').trim();if(!text&&!state.attachment)return;const c=roleContacts().find(c=>c.id===state.contact);const key=messageThreadKey();if(!state.messages[key])state.messages[key]=defaultThreadMessages(c);state.messages[key].push({own:true,text:text+(state.attachment?`\n📎 ${state.attachment}`:''),time:new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})});state.attachment=null;state.messageDrafts[key]='';persist();render();document.getElementById('messageInput')?.focus();return}
 if(form.id==='coachForm'){sendCoachAnswer(form,values.answer);return}
 if(form.id==='coachAIForm'){sendAIQuestion(values.question);return}
 if(form.id==='teacherCoachForm'){generateTeacherDraft(values);return}
 if(form.id==='accountForm'){saveAccountForm(form,values);return}
 if(form.id==='studentClassForm'){saveStudentClass(form,values.classId||'');return}
 if(form.id==='sessionForm'){saveSession(form,values);return}
 if(form.id==='helpForm'){download(`Demande d'assistance - Madrassati Maâk\n\nSujet : ${values.subject}\n\n${values.message}\n\nCe document n'a pas été envoyé.\n`,'Madrassati-Demande-Assistance.txt');toast('Votre demande est prête à être transmise à votre établissement.');form.reset()}
});
document.addEventListener('keydown',event=>{if(event.target?.id==='quickSearchInput'&&['Enter','ArrowDown'].includes(event.key)){event.preventDefault();const first=document.querySelector('.catalog-result');if(event.key==='Enter')first?.click();else first?.focus();return}const typing=['input','textarea','select'].includes((event.target?.tagName||'').toLowerCase())||event.target?.isContentEditable;if(((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'||event.key==='/'&&!typing&&!event.ctrlKey&&!event.metaKey)&&state.page!=='connexion'&&!document.querySelector('.modal')){event.preventDefault();openQuickSearch();return}if(event.key==='Escape'){closeModal();closePopovers();document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.mobile-overlay')?.classList.remove('visible');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');if('speechSynthesis' in window)speechSynthesis.cancel()}if(event.key==='Tab'){const modal=document.querySelector('.modal')||document.querySelector('.sidebar.open');if(!modal)return;const items=[...modal.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')].filter(el=>!el.classList.contains('hidden'));if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
