window.addEventListener('online',syncHomeworkConnection);
window.addEventListener('offline',syncHomeworkConnection);
window.addEventListener('focus',refreshGradePeriod);
window.addEventListener('storage',event=>{
  if(event.key===ACCOUNTS_KEY){state.accounts=readAccountStore()||initialAccounts.map(normalizeAccount);if(!resettingDemo)render();return}
  if(event.key===GRADE_PERIOD_KEY){refreshGradePeriod();return}
  if(event.key===GRADEBOOK_KEY){if(state.page==='notes'&&state.role!=='administration'&&!document.querySelector('.modal'))render();return}
  if(![HOMEWORK_KEY,LIBRARY_KEY].includes(event.key))return;
  if(event.key===HOMEWORK_KEY){
    cachedHomework=readHomeworkBoard();
    const homeworkId=document.querySelector('.modal [data-homework-id]')?.dataset.homeworkId;
    if(homeworkId&&!findHomework(homeworkId)){
      closeModal();
      toast('Cette publication n’est plus disponible.');
    }
  }
  if(!document.querySelector('.modal'))render();
});
